def finding(raw, index):
    fid, name, description, finding_kind, refs, value_kind, required = raw
    kinds = QUESTION_KINDS[index % len(QUESTION_KINDS)]
    return {
        "id": fid, "name": name, "description": description, "source_refs": refs,
        "questions": [
            {"id":fid+"-q01","text":f"What identities, classes, parties, authority and values define {name.lower()}?","kind":kinds[0],"answer_data":["identifiers and classes","actors and authority","values and references","explicit unknowns"]},
            {"id":fid+"-q02","text":f"Which rule, source record, calculation, event time and knowledge time support {name.lower()}?","kind":kinds[1],"answer_data":["legal source","evidence or calculation","event and knowledge time","provenance"]},
            {"id":fid+"-q03","text":f"How may {name.lower()} be validated, disputed, corrected, superseded, retained and disclosed without silently deciding tax liability?","kind":kinds[2],"answer_data":["validation controls","dispute route","successor record","retention and access","non-adjudication boundary"]},
        ],
        "data_elements":[{"id":fid+"-data","name":name+" data","description":"Structured authority-qualified tax-obligation data for "+name.lower()+".","value_kind":value_kind,"cardinality":"1" if required else "0..n","required":required,"source_refs":refs}],
        "artifacts":[{"id":fid+"-record","name":name+" record","description":"Versioned evidence-bearing record for "+name.lower()+" with legal source, event and knowledge time, provenance and access marking.","media_or_form":["logical tax obligation record","authoritative tax-system or source-evidence reference"],"serial":True,"identity_strategy":"Obligation identifier plus "+fid+" assertion or event identifier; taxpayer name, tax type, period, date and digest never identify the obligation alone.","source_refs":refs}],
        "inline_only_rationale":None,
        "_kind":finding_kind,
    }

def structure():
    cursor = 0
    bundles = []
    for bid, name, description, rationale, refs, layers in BUNDLES:
        out_layers = []
        for lid, lname, ldescription, lrefs, findings in layers:
            out_findings = []
            for raw in findings:
                item = finding(raw, cursor)
                item.pop("_kind")
                out_findings.append(item)
                cursor += 1
            out_layers.append({"id":lid,"name":lname,"description":ldescription,"source_refs":lrefs,"findings":out_findings})
        bundles.append({"id":bid,"name":name,"description":description,"rationale":rationale,"source_refs":refs,"layers":out_layers})
    return {"bundles":bundles}

